#!/usr/bin/env python3
"""Reconstruct a scrolling terminal transcript from per-frame OCR.

Usage: reconstruct.py <outdir> [--fuzzy 0.8]

Frames are ordered by index. We keep a global list of lines. For each
frame we find the largest K such that the frame's last K lines match the
global list's last K lines (fuzzy). The frame lines before that matched
suffix are new: append them, folding typing continuations into the last
global line.
"""
import difflib
import json
import os
import sys

def sim(a, b):
    return difflib.SequenceMatcher(None, a, b).ratio()

def main():
    outdir = sys.argv[1]
    args = sys.argv[2:]
    fuzzy = 0.8
    if "--fuzzy" in args:
        i = args.index("--fuzzy"); fuzzy = float(args[i + 1])

    files = sorted(f for f in os.listdir(outdir)
                   if f.startswith("frame_") and f.endswith(".json"))
    frames = []
    for f in files:
        with open(os.path.join(outdir, f)) as fh:
            frames.append(json.load(fh))

    global_lines = []  # list of [first_frame_idx, text]

    for fr in frames:
        lines = fr["lines"]
        n = fr["idx"]
        Kmax = min(len(lines), len(global_lines))
        matched = 0
        for K in range(Kmax, 0, -1):
            gseg = [t for _, t in global_lines[len(global_lines) - K:]]
            fseg = lines[len(lines) - K:]
            if all(sim(a, b) >= fuzzy for a, b in zip(gseg, fseg)):
                matched = K
                break
        f_start = len(lines) - matched
        for new_line in lines[f_start:]:
            if not new_line:
                continue
            if global_lines:
                gl = global_lines[-1][1]
                if new_line.startswith(gl) and len(new_line) > len(gl):
                    global_lines[-1][1] = new_line
                    continue
                if gl.startswith(new_line):
                    continue
            global_lines.append([n, new_line])

    for n, t in global_lines:
        print(f"{n:06d}\t{t}")

if __name__ == "__main__":
    main()

